DROP TABLE IF EXISTS `appointment_automatic_sms`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `appointment_automatic_sms` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `appointment_id` bigint(20) unsigned NOT NULL,
  `project_id` bigint(20) unsigned DEFAULT NULL,
  `scenario_id` bigint(20) unsigned DEFAULT NULL,
  `scenario_step_id` bigint(20) unsigned DEFAULT NULL,
  `service_name` varchar(255) DEFAULT NULL,
  `inventory_tag` varchar(255) NOT NULL,
  `sms_template` varchar(255) DEFAULT NULL,
  `days_after` smallint(5) unsigned NOT NULL,
  `send_at` time NOT NULL,
  `scheduled_at` datetime DEFAULT NULL,
  `is_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `status` varchar(40) NOT NULL DEFAULT 'waiting_completion',
  `attempts` smallint(5) unsigned NOT NULL DEFAULT 0,
  `sent_at` datetime DEFAULT NULL,
  `disabled_at` datetime DEFAULT NULL,
  `last_error` text DEFAULT NULL,
  `provider_response` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`provider_response`)),
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `appointment_auto_sms_step_unique` (`appointment_id`,`scenario_step_id`),
  KEY `appointment_automatic_sms_project_id_foreign` (`project_id`),
  KEY `appointment_automatic_sms_scenario_id_foreign` (`scenario_id`),
  KEY `appointment_automatic_sms_scenario_step_id_foreign` (`scenario_step_id`),
  KEY `appointment_auto_sms_summary_index` (`appointment_id`,`is_enabled`,`status`),
  KEY `appointment_automatic_sms_scheduled_at_index` (`scheduled_at`),
  KEY `appointment_automatic_sms_is_enabled_index` (`is_enabled`),
  KEY `appointment_automatic_sms_status_index` (`status`),
  CONSTRAINT `appointment_automatic_sms_appointment_id_foreign` FOREIGN KEY (`appointment_id`) REFERENCES `appointments` (`id`) ON DELETE CASCADE,
  CONSTRAINT `appointment_automatic_sms_project_id_foreign` FOREIGN KEY (`project_id`) REFERENCES `automatic_sms_projects` (`id`) ON DELETE SET NULL,
  CONSTRAINT `appointment_automatic_sms_scenario_id_foreign` FOREIGN KEY (`scenario_id`) REFERENCES `automatic_sms_scenarios` (`id`) ON DELETE SET NULL,
  CONSTRAINT `appointment_automatic_sms_scenario_step_id_foreign` FOREIGN KEY (`scenario_step_id`) REFERENCES `automatic_sms_scenario_steps` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

