--
-- Table structure for table `appointment_financial_transactions`
--

DROP TABLE IF EXISTS `appointment_financial_transactions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `appointment_financial_transactions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `appointment_id` bigint(20) unsigned NOT NULL,
  `patient_id` bigint(20) unsigned DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `type` varchar(30) NOT NULL,
  `amount` decimal(15,0) NOT NULL,
  `payment_method` varchar(100) DEFAULT NULL,
  `payment_account` varchar(100) DEFAULT NULL,
  `reference_number` varchar(190) DEFAULT NULL,
  `due_date` date DEFAULT NULL,
  `reason` text DEFAULT NULL,
  `metadata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`metadata`)),
  `occurred_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `voided_at` timestamp NULL DEFAULT NULL,
  `voided_by` bigint(20) unsigned DEFAULT NULL,
  `settled_at` timestamp NULL DEFAULT NULL,
  `settled_by` bigint(20) unsigned DEFAULT NULL,
  `settlement_transaction_id` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `appointment_financial_transactions_created_by_foreign` (`created_by`),
  KEY `aft_patient_type_time_idx` (`patient_id`,`type`,`occurred_at`),
  KEY `aft_appointment_type_idx` (`appointment_id`,`type`),
  KEY `appointment_financial_transactions_voided_by_foreign` (`voided_by`),
  KEY `aft_appointment_type_voided_idx` (`appointment_id`,`type`,`voided_at`),
  KEY `appointment_financial_transactions_settled_by_foreign` (`settled_by`),
  KEY `aft_settlement_tx_fk` (`settlement_transaction_id`),
  KEY `aft_appointment_type_settled_idx` (`appointment_id`,`type`,`settled_at`),
  CONSTRAINT `aft_settlement_tx_fk` FOREIGN KEY (`settlement_transaction_id`) REFERENCES `appointment_financial_transactions` (`id`) ON DELETE SET NULL,
  CONSTRAINT `appointment_financial_transactions_appointment_id_foreign` FOREIGN KEY (`appointment_id`) REFERENCES `appointments` (`id`) ON DELETE CASCADE,
  CONSTRAINT `appointment_financial_transactions_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `appointment_financial_transactions_patient_id_foreign` FOREIGN KEY (`patient_id`) REFERENCES `patients` (`id`) ON DELETE SET NULL,
  CONSTRAINT `appointment_financial_transactions_settled_by_foreign` FOREIGN KEY (`settled_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `appointment_financial_transactions_voided_by_foreign` FOREIGN KEY (`voided_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=72 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

