--
-- Table structure for table `patient_media_folders`
--

DROP TABLE IF EXISTS `patient_media_folders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `patient_media_folders` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `patient_id` bigint(20) unsigned NOT NULL,
  `parent_id` bigint(20) unsigned DEFAULT NULL,
  `name` varchar(255) NOT NULL,
  `folder_type` varchar(30) DEFAULT NULL,
  `folder_date` varchar(20) DEFAULT NULL,
  `inventory_id` bigint(20) unsigned DEFAULT NULL,
  `inventory_section_id` bigint(20) unsigned DEFAULT NULL,
  `inventory_section_ids` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`inventory_section_ids`)),
  `services` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`services`)),
  `upload_description` text DEFAULT NULL,
  `upload_usage_consent` tinyint(1) NOT NULL DEFAULT 1,
  `upload_is_featured` tinyint(1) NOT NULL DEFAULT 0,
  `photo_processing_settings` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`photo_processing_settings`)),
  `sort_order` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `patient_media_folders_parent_id_foreign` (`parent_id`),
  KEY `patient_media_folders_patient_id_parent_id_index` (`patient_id`,`parent_id`),
  KEY `patient_media_folders_inventory_id_foreign` (`inventory_id`),
  KEY `pmf_patient_parent_type_index` (`patient_id`,`parent_id`,`folder_type`),
  KEY `patient_media_folders_inventory_section_id_foreign` (`inventory_section_id`),
  CONSTRAINT `patient_media_folders_inventory_id_foreign` FOREIGN KEY (`inventory_id`) REFERENCES `inventories` (`id`) ON DELETE SET NULL,
  CONSTRAINT `patient_media_folders_inventory_section_id_foreign` FOREIGN KEY (`inventory_section_id`) REFERENCES `inventory_sections` (`id`) ON DELETE SET NULL,
  CONSTRAINT `patient_media_folders_parent_id_foreign` FOREIGN KEY (`parent_id`) REFERENCES `patient_media_folders` (`id`) ON DELETE CASCADE,
  CONSTRAINT `patient_media_folders_patient_id_foreign` FOREIGN KEY (`patient_id`) REFERENCES `patients` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=48 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `patient_media_folders`
--

