DROP TABLE IF EXISTS `patients`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `patients` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `first_name` varchar(255) DEFAULT NULL,
  `last_name` varchar(255) DEFAULT NULL,
  `phone` varchar(255) DEFAULT NULL,
  `file_number` varchar(255) DEFAULT NULL,
  `gender` varchar(255) DEFAULT NULL,
  `birth_date` date DEFAULT NULL,
  `area` varchar(255) DEFAULT NULL,
  `city` varchar(255) DEFAULT NULL,
  `financial_status` varchar(255) DEFAULT NULL,
  `customer_level` varchar(30) DEFAULT NULL,
  `patient_history` text DEFAULT NULL,
  `medical_history` text DEFAULT NULL,
  `national_id` varchar(20) DEFAULT NULL,
  `foreign_national_code` varchar(30) DEFAULT NULL,
  `father_name` varchar(255) DEFAULT NULL,
  `marital_status` varchar(20) DEFAULT NULL,
  `marriage_date` varchar(20) DEFAULT NULL,
  `education` varchar(255) DEFAULT NULL,
  `weight` decimal(5,1) DEFAULT NULL,
  `second_phone` varchar(30) DEFAULT NULL,
  `address` text DEFAULT NULL,
  `profile_photo_path` varchar(255) DEFAULT NULL,
  `profile_thumbnail_path` varchar(255) DEFAULT NULL,
  `wallet_balance` decimal(15,2) NOT NULL DEFAULT 0.00,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `patients_file_number_unique` (`file_number`),
  KEY `patients_birth_date_report_idx` (`birth_date`),
  KEY `patients_first_name_report_idx` (`first_name`),
  KEY `patients_last_name_report_idx` (`last_name`),
  KEY `patients_phone_report_idx` (`phone`),
  KEY `patients_gender_report_idx` (`gender`),
  KEY `patients_city_report_idx` (`city`)
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
