  KEY `voip_calls_patient_id_foreign` (`patient_id`),
  KEY `voip_calls_last_event_at_id_index` (`last_event_at`,`id`),
  KEY `voip_calls_phone_index` (`phone`),
  CONSTRAINT `voip_calls_patient_id_foreign` FOREIGN KEY (`patient_id`) REFERENCES `patients` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=37 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
